        # @param path Destination checkout path on the calling client. Relative paths start at the client's working directory. Omit to use the calling client's current local workspace root.
        # @param from Earlier workspace state to compare against. For Git integration, live inputs are snapshotted at export time; use a snapshot to retain the baseline of a previous export.
        def export(path: nil, from: nil)
          @query.select("export", path:, from:).execute(allow_nil: true)
          nil
        end

        # Read a configuration value from dagger.toml.
        #
        # If key is empty, returns the full config.
        #
        # If key points to a scalar, returns the value.
        #
        # If key points to a table, returns flattened dotted-key output.
        # @param key Dotted key path (e.g. modules.greeter.source). Empty for full config.
        # @param effective Include the selected environment, user overrides, and legacy workspace settings.
        def config_read(key: nil, effective: nil)
          @query.select("configRead", key:, effective:).execute
        end

        # Installed name of the module selected as the workspace main, or an empty string when none is selected.
        #
        # Reflects the selected env's effective view. Fails if several modules are selected.
        def main
          @query.select("main").execute
        end

        # Compatibility alias for main.
        # @deprecated Use main.
        def entrypoint
          @query.select("entrypoint").execute
        end

        # List named environments defined in the workspace configuration.
        def env_list
          @query.select("envList").execute
        end

        # List modules defined in the workspace configuration.
        #
        # Reflects the selected env's effective view.
        def modules
          @query.select("modules").execute_object_list(WorkspaceModule)
        end

        # Return a module defined in the workspace configuration.
        #
        # Reflects the selected env's effective view.
        # @param name Module name to inspect.
        def module(name:)
          WorkspaceModule.new(@query.select("module", name:).reevaluate)
        end

        # Load a module source from a path within the workspace.
        #
        # Relative paths (e.g., "foo") resolve from the workspace cwd; absolute paths (e.g., "/foo") resolve from the workspace root.
        #
        # Fails if the path does not point to an initialized module.
        # @param path Location of the module source to load, relative to the workspace cwd or absolute from the workspace root.
        def module_source(path:)
          ModuleSource.new(@query.select("moduleSource", path:))
        end

        # Current location within the workspace root.
        #
        # The workspace root is returned as "/".
        #
        # Relative paths in workspace APIs resolve from here.
        def cwd
          @query.select("cwd").execute
        end

        # Discover static object artifacts from workspace modules without evaluating their values.
        #
        # Omits the paths that the workspace's check.skip, generate.skip, and up.skip settings skip.
        # @param include Only include artifacts matching these path patterns, as with checks and services. A path selects that path and its children.
        def artifacts(include: nil)
          Artifacts.new(@query.select("artifacts", include:))
        end

        # Plan the explicit migration needed for the current workspace.
        #
        # Include installed local modules and their local dependencies. Other module candidates remain unchanged unless selected.
        #
        # The returned plan has an empty changeset and no steps when no migration is needed.
        # @param modules Additional local modules to migrate. Relative paths start at the workspace cwd; absolute paths start at the workspace root.
        def migrate(modules: nil)
          WorkspaceMigration.new(@query.select("migrate", modules:).reevaluate)
        end

        # Canonical Dagger address of the workspace location, or an opaque identity for synthetic workspaces.
        def address
          @query.select("address").execute
        end
      end
    end
  end
end
